function levenshtein(a,b){
  a=String(a||""); b=String(b||"");
  var m=a.length,n=b.length;
  if(!m)return n;
  if(!n)return m;
  var prev=new Array(n+1),cur=new Array(n+1);
  for(var j=0;j<=n;j++)prev[j]=j;
  for(var i=1;i<=m;i++){
    cur[0]=i;
    for(var j2=1;j2<=n;j2++){
      var cost=a.charAt(i-1)===b.charAt(j2-1)?0:1;
      cur[j2]=Math.min(
        cur[j2-1]+1,
        prev[j2]+1,
        prev[j2-1]+cost
      );
    }
    var tmp=prev; prev=cur; cur=tmp;
  }
  return prev[n];
}

function wordList(value){
  return clean(value).toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
}

function fuzzyWordMatch(needle,word){
  if(!needle||!word)return false;
  if(word.indexOf(needle)>=0||needle.indexOf(word)>=0)return true;

  // typo tolerance:
  // 3-4 chars => 1 edit
  // 5+ chars   => 2 edits
  var limit=needle.length>=5?2:(needle.length>=3?1:0);
  if(!limit)return false;

  if(Math.abs(needle.length-word.length)>limit)return false;
  return levenshtein(needle,word)<=limit;
}

function matchesQuery(r,q){
  var parts=tokens(q);
  if(!parts.length)return true;

  var titleWords=wordList(r.title||"");
  var slugWords=wordList(String(r.slug||"").replace(/[-_]+/g," "));
  var words=titleWords.concat(slugWords);

  // Broad search: ANY typed word matching ANY title/slug word is enough.
  for(var i=0;i<parts.length;i++){
    for(var j=0;j<words.length;j++){
      if(fuzzyWordMatch(parts[i],words[j]))return true;
    }
  }
  return false;
}

function searchScore(r,q){
  var title=clean(r.title||"").toLowerCase();
  var slug=clean(String(r.slug||"").replace(/[-_]+/g," ")).toLowerCase();
  var phrase=clean(q).toLowerCase();
  var qwords=tokens(q);
  var words=wordList(title+" "+slug);
  var score=0;

  if(title===phrase)score+=1000;
  if(title.indexOf(phrase)===0)score+=500;
  if(title.indexOf(phrase)>=0)score+=250;
  if(slug.indexOf(phrase)>=0)score+=180;

  qwords.forEach(function(qw){
    words.forEach(function(w){
      if(qw===w)score+=120;
      else if(w.indexOf(qw)===0)score+=80;
      else if(w.indexOf(qw)>=0)score+=50;
      else{
        var d=levenshtein(qw,w);
        if(d===1)score+=35;
        else if(d===2&&qw.length>=5)score+=15;
      }
    });
  });

  return score;
}


