function searchCards(){
  var records=seriesRecords(document);

  // The actual /tim-kiem page already decides which titles match,
  // so do not apply our own fuzzy/exact filter here.
  return records.map(function(r){
    var card=recordCard(r,"Search");

    // Try to pull extra card metadata without depending on it.
    var anchor=null;
    try{
      anchor=Array.prototype.slice.call(document.querySelectorAll("a[href*='/manga/']")).find(function(a){
        return seriesUrl(a.href||a.getAttribute("href"))===r.href;
      });
    }catch(e){}

    if(anchor){
      var node=anchor;
      var text="";
      for(var i=0;i<5&&node;i++,node=node.parentElement){
        var t=clean(node.textContent);
        if(t.length>text.length)text=t;
      }

      var chapter=(text.match(/(?:Chap(?:ter)?\.?\s*)(\d+(?:\.\d+)?)/i)||[])[1]||"";
      var rating=(text.match(/(?:★\s*)?(\d+(?:\.\d+)?)\s*(?:\||$)/)||[])[1]||"";

      if(chapter)card.field3="Ch. "+chapter;
      if(rating)card.field4="★ "+rating;
    }

    return card;
  });
}

