  if(finished)return;finished=true;
  var n=saved();if(n)n.textContent=JSON.stringify(value);
  try{window.webkit.messageHandlers.EXECUTE_KETSU_ASYNC.postMessage('');}catch(e){}
}
function routeParts(){
  try{
    var u=new URL(location.href);
    if(u.origin!==SITE)return [];
    return u.pathname.split('/').filter(Boolean);
  }catch(e){return [];}
}
function validSlug(slug){return /^[a-z0-9][a-z0-9._-]*$/i.test(clean(slug));}
function seriesUrl(slug){return SITE+'/manga/'+slug;}
function titleSlug(){
  var p=routeParts();
  return p.length===2&&p[0]==='manga'&&validSlug(p[1])?p[1]:'';
}
function readerRoute(){
  var p=routeParts();
  if(p.length!==3||p[0]!=='manga'||!validSlug(p[1])||!validSlug(p[2]))return null;
  return {slug:p[1],chapter:p[2]};
}
function validManga(p,slug){
  return !!(validSlug(slug)&&p&&p.manga&&clean(p.manga.slug).toLowerCase()===clean(slug).toLowerCase());
}
function safeHttpUrl(value){
  try{
    if(value&&typeof value==='object'){
      value=value.url||value.src||value.href||value.path||value.image||value.file||'';
    }
    if(typeof value!=='string')return '';
    value=clean(value);
    if(!value)return '';
    var u=new URL(value,location.href);
    return /^https?:$/.test(u.protocol)?u.href:'';
  }catch(e){return '';}
}
function imageUrl(value){
  return safeHttpUrl(value);
}
function coverUrl(manga){
  manga=manga||{};
  var keys=[
    'cover_url','thumb_url','thumbnail_url','image_url','poster_url',
    'cover','thumb','thumbnail','image','poster'
  ];
  for(var i=0;i<keys.length;i++){
    var v=manga[keys[i]],u=safeHttpUrl(v);
    if(u&&!/favicon|logo(?:[._-]|$)/i.test(u))return u;
  }
  try{
    var imgs=Array.prototype.slice.call(document.images||[]);
    for(var j=0;j<imgs.length;j++){
      var img=imgs[j];
      var raw=img.currentSrc||img.getAttribute('src')||img.getAttribute('data-src')||
              img.getAttribute('data-lazy-src')||img.getAttribute('data-original')||'';
      var u2=safeHttpUrl(raw);
      if(!u2||/favicon|logo(?:[._-]|$)/i.test(u2))continue;
      var w=Number(img.naturalWidth||img.width||0),h=Number(img.naturalHeight||img.height||0);
      if((w>=120&&h>=150)||h>w)return u2;
    }
  }catch(e){}
  return '';
}
function pageUrl(value){
  return safeHttpUrl(value);
}
function chapterImageValue(item){
  if(typeof item==='string')return item;
  if(!item||typeof item!=='object')return '';
  return item.src||item.url||item.image||item.path||item.file||item.original||'';
}
function chapters(p,slug){
  if(!Array.isArray(p.chapters)||!p.chapters.length)return [];
  var seen={},list=[];
  for(var i=0;i<p.chapters.length;i++){
    var c=p.chapters[i]||{},chapterSlug=clean(c.slug),num=Number(c.order);
    if(!/^[a-z0-9._-]+$/i.test(chapterSlug)||c.order==null||clean(c.order)===''||!Number.isFinite(num)||seen[chapterSlug])continue;
    seen[chapterSlug]=true;
    list.push({
      number:num,
      index:i,
      chapter:new Chapter(
        clean(c.name)||('Chapter '+num),
        req(seriesUrl(slug)+'/'+chapterSlug,seriesUrl(slug)),
        false
      )
    });
  }
  list.sort(function(a,b){return a.number-b.number||a.index-b.index;});
  return list.map(function(item){return item.chapter;});
}
function emit(p,slug){
  var okay=!!slug&&validManga(p,slug),m=okay?p.manga:{},list=okay?chapters(p,slug):[];
  var genre=Array.isArray(m.genres)?m.genres.map(function(g){return clean(g&&g.name);}).filter(Boolean):[];
  var description=clean(m.pilot||m.description||m.note).replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
  done(new Info(new MR('','',E,null),extra(),new JC(false,false,''),new InfoOutput(
    req(coverUrl(m)||ICON,seriesUrl(slug||''),'image/*,*/*;q=0.8'),
    okay?clean(m.name):'',
    req(okay?seriesUrl(slug):'',seriesUrl(slug||'')),
    description,genre,'Manhwa18','','','Chapters: '+list.length,list
  )));
}
function run(n){
  var slug=titleSlug();
  if(!slug)return emit({},'');
  var p=props();
  if(validManga(p,slug)||n>=30)return emit(p,slug);
  setTimeout(function(){run(n+1);},250);
}
setTimeout(function(){run(0);},100);

var KETSU_ASYNC=true;
function MR(url,method,headers,body){this.url=url;this.method=method;this.headers=headers;this.httpBody=body;}
function KV(key,value){this.key=key;this.value=value;}
function Extra(commands,extraInfo){this.commands=commands;this.extraInfo=extraInfo;}
function Commands(commandName,params){this.commandName=commandName;this.params=params;}
function JC(removeJavascript,loadInWebView,javaScript){this.removeJavascript=removeJavascript;this.loadInWebView=loadInWebView;this.javaScript=javaScript;}
function Data(image,title,description,field1,field2,field3,field4,isChapter,link,openInWebView){
  this.image=image;this.title=title;this.description=description;this.field1=field1;this.field2=field2;
  this.field3=field3;this.field4=field4;this.isChapter=isChapter;this.link=link;this.openInWebView=openInWebView||false;
}
function Output(cellDesing,orientation,defaultLayout,paging,section,layout,data){
  this.cellDesing=cellDesing;this.orientation=orientation;this.defaultLayout=defaultLayout;this.paging=paging;
  this.section=section;this.layout=layout;this.data=data;
}
function Section(sectionName,separator){this.sectionName=sectionName;this.separator=separator;}
function MainPage(request,extra,javascriptConfig,output){this.request=request;this.extra=extra;this.javascriptConfig=javascriptConfig;this.output=output;}
function Search(request,extra,separator,javascriptConfig,output){this.request=request;this.extra=extra;this.separator=separator;this.javascriptConfig=javascriptConfig;this.output=output;}
function Info(request,extra,javascriptConfig,output){this.request=request;this.extra=extra;this.javascriptConfig=javascriptConfig;this.output=output;}
function Chapter(chapName,link,openInWebView){this.chapName=chapName;this.link=link;this.openInWebView=openInWebView;}
function InfoOutput(image,title,link,description,genres,field1,field2,field3,field4,chapters){
  this.image=image;this.title=title;this.link=link;this.description=description;this.genres=genres;
  this.field1=field1;this.field2=field2;this.field3=field3;this.field4=field4;this.chapters=chapters;
}
function Chapters(request,extra,javascriptConfig,output){this.request=request;this.extra=extra;this.javascriptConfig=javascriptConfig;this.output=output;}
function ChapterOutput(videos,images,text){this.videos=videos;this.images=images;this.text=text;}

var SITE='https://manhwa18.net', ICON=SITE+'/favicon.ico', finished=false;
var E=[new KV('','')];

