function emit(p,r){
  var okay=!!r;

  // Some reader pages expose mangaSlug; others only expose chapterImages.
  // Only reject when an exposed slug clearly conflicts with the current route.
  if(okay){
    var exposedSlug=clean(
      (p&&p.mangaSlug)||
      (p&&p.manga&&p.manga.slug)||
      (p&&p.slug)||
      ''
    ).toLowerCase();
    if(exposedSlug&&exposedSlug!==r.slug)okay=false;
  }

  // Validate against listChapters when that list actually exposes usable slugs.
  if(okay&&Array.isArray(p.listChapters)&&p.listChapters.length){
    var identifiable=[];
    for(var j=0;j<p.listChapters.length;j++){
      var c=p.listChapters[j]||{};
      var s=clean(c.slug||c.chapter_slug||c.chapterSlug||'');
      if(s)identifiable.push({slug:s,id:c.id});
    }
    if(identifiable.length){
      var hit=identifiable.find(function(c){return c.slug===r.chapter;});
      if(!hit)okay=false;
      else if(p.chapterId!=null&&hit.id!=null&&String(hit.id)!==String(p.chapterId))okay=false;
    }
  }

  var source=okay&&Array.isArray(p.chapterImages)?p.chapterImages:[],urls=[];
  for(var i=0;i<source.length;i++){
    var url=pageUrl(chapterImageValue(source[i]));
    if(url)urls.push(url);
  }

  var images=urls.map(function(url){
    return req(url,location.href,'image/avif,image/webp,image/apng,image/*,*/*;q=0.8');
  });

  done(new Chapters(new MR('','',E,null),extra(),new JC(false,false,''),
    new ChapterOutput(null,images,null)));
}
function run(n){
  var r=readerRoute();
  if(!r)return emit({},null);
  var p=props();
  if(Array.isArray(p.chapterImages)||n>=30)return emit(p,r);
  setTimeout(function(){run(n+1);},250);
}
